(()=>{
  const root=document.getElementById('world');if(!root)return;
  let mountedBar=null,dialog=null;
  function sync(){
    observer.disconnect();
    try{
      const bar=document.getElementById('v571-services')||root.querySelector('.v57-services');
      if(!bar){if(dialog){dialog.remove();dialog=null;}mountedBar=null;return;}
      bar.querySelector('#free-deadmines-entry')?.remove();
      const actions=Array.from(bar.children).filter(n=>n.tagName==='BUTTON'&&n.id!=='az-services-toggle');
      if(mountedBar===bar&&!actions.length)return;
      if(mountedBar!==bar){
        if(dialog)dialog.remove();
        dialog=document.createElement('dialog');dialog.id='az-services-menu';dialog.className='az-sheet';dialog.setAttribute('aria-label','Меню карты');dialog.style.cssText='width:min(360px,90vw);max-height:85dvh;overflow:auto';
        const title=document.createElement('h2');title.textContent='Меню';
        const close=document.createElement('button');close.type='button';close.className='btn';close.textContent='Закрыть';close.dataset.servicesClose='';close.onclick=()=>dialog.close();
        dialog.append(title,close);document.body.append(dialog);
        dialog.addEventListener('click',event=>{const button=event.target.closest('button');if(button&&!button.disabled&&!button.hasAttribute('data-services-close'))dialog.close();},true);
        mountedBar=bar;
      }
      for(const action of actions){action.style.display='block';action.style.margin='8px 0';dialog.append(action);}
      if(!bar.querySelector('#az-services-toggle')){
        const toggle=document.createElement('button');toggle.id='az-services-toggle';toggle.type='button';toggle.className='btn';toggle.textContent='Меню';toggle.setAttribute('aria-haspopup','dialog');toggle.setAttribute('aria-controls','az-services-menu');toggle.onclick=()=>{if(!dialog.open)dialog.showModal();};bar.append(toggle);
      }
    }finally{observer.observe(root,{childList:true,subtree:true});}
  }
  const observer=new MutationObserver(sync);sync();
})();
